{"path":"assets/css/styles.css","content":"/* Minimal poetic aesthetic, system fonts only */
:root{--bg:#fbfdfb;--muted:#6b6b6b;--accent:#1f8a5f;--accent-2:#2a6b4f;--card:#fff;--glass:rgba(255,255,255,0.7)}
*{box-sizing:border-box}
html,body{height:100%}
body.aura{font-family:Inter,ui-sans-serif,system-ui,-apple-system,"Segoe UI",Roboto,"Helvetica Neue",Arial;line-height:1.45;color:#123; background:linear-gradient(180deg,#f7faf7 0%,var(--bg) 100%);-webkit-font-smoothing:antialiased}
.wrap{max-width:1080px;margin:0 auto;padding:28px}
.site-header{background:transparent;padding:14px 0}
.brand{font-weight:700;color:var(--accent-2);text-decoration:none;font-size:1.05rem}
.main-nav{display:inline-block;float:right}
.main-nav a{margin-left:14px;color:#234; text-decoration:none;font-size:0.95rem}
.main-nav .cta{background:var(--accent);color:#fff;padding:8px 12px;border-radius:8px}
.main-nav .muted{opacity:0.7}
.hero{padding:40px 0}
.hero-grid{display:grid;grid-template-columns:1fr 360px;gap:24px;align-items:center}
.hero-copy h1{font-size:2rem;margin:0 0 8px;color:var(--accent-2)}
.lead{font-size:1.05rem;margin:0 0 8px}
.meta{color:var(--muted)}
.button{display:inline-block;padding:10px 14px;border-radius:8px;border:1px solid rgba(18,18,18,0.06);text-decoration:none;color:var(--accent-2);background:transparent;cursor:pointer}
.button.primary{background:var(--accent);color:#fff;border:none}
.button.ghost{background:#fff;border:1px solid #e6eef0}
.button.big{padding:14px 18px}
.hero-art .pattern{width:100%;height:220px;border-radius:10px;box-shadow:0 10px 30px rgba(30,50,40,0.05)}
.panel{background:transparent;padding:24px 0}
.panel-head h2{margin:0 0 6px;font-size:1.25rem;color:#123}
.panel-body{margin-top:12px}
.planner-grid{display:grid;grid-template-columns:360px 1fr;gap:20px}
.planner{background:var(--card);padding:16px;border-radius:10px;box-shadow:0 6px 20px rgba(10,30,20,0.03)}
.planner label{display:block;font-size:0.9rem;margin-bottom:10px;color:#234}
.planner input[type=text],.planner input[type=number],.planner select{width:100%;padding:8px;border-radius:8px;border:1px solid #e6efe9}
.chips label{display:inline-block;margin-right:8px;font-size:0.85rem}
.form-actions{display:flex;gap:8px;margin-top:8px}
.planner-output textarea{width:100%;padding:12px;border-radius:8px;border:1px solid #e9f2ed;background:linear-gradient(180deg,#fff,#fbfefb)}
.output-actions{display:flex;gap:8px;margin-top:8px}
.diagnostic-grid{display:flex;gap:14px}
.diag-card{background:var(--card);padding:12px;border-radius:8px;flex:1}
.scale button{margin-right:6px;padding:8px 10px;border-radius:8px;border:1px solid #e6efe9;background:#fff}
.habits-grid{display:grid;grid-template-columns:420px 1fr;gap:20px}
.habit-form input,.habit-form select{width:100%;padding:8px;margin-top:6px;border-radius:8px;border:1px solid #e6efe9}
.checklist{background:var(--card);padding:12px;border-radius:10px;border:1px solid #eef6f0}
.checklist li{padding:8px 0;border-bottom:1px dashed #eef6f0}
.pricing-grid{display:flex;gap:14px}
.card{background:var(--card);padding:16px;border-radius:10px;flex:1;border:1px solid #eef6f0}
.card.featured{border-color:rgba(31,138,95,0.15);box-shadow:0 10px 30px rgba(31,138,95,0.06)}
.price{font-weight:700;font-size:1.2rem;color:var(--accent-2)}
.cta{background:linear-gradient(90deg,var(--accent),var(--accent-2));color:#fff;padding:18px;border-radius:10px;display:flex;align-items:center;justify-content:space-between}
.cta .big{font-size:1rem}
.site-footer{border-top:1px solid #eef6f0;margin-top:40px;padding:18px 0;color:var(--muted)}
.footer-grid{display:flex;justify-content:space-between;align-items:center}
.foot-nav a{margin-left:12px;color:var(--muted);text-decoration:none}
@media(max-width:880px){
  .hero-grid{grid-template-columns:1fr}
  .planner-grid,.habits-grid{grid-template-columns:1fr}
  .main-nav{float:none;display:flex;gap:8px;margin-top:10px}
}
.small{font-size:0.85rem}
.muted{color:var(--muted)}"} 
{"path":"assets/js/main.js","content":"// Session Planner and Habit Builder
(function(){
  // Helpers
  function el(id){return document.getElementById(id)}
  function textEscape(s){return s.replace(/\n/g,'\\n')}

  // Session Planner
  var form = el('sessionForm');
  var generateBtn = el('generatePlan');
  var clearBtn = el('clearPlan');
  var output = el('planOutput');
  var copyBtn = el('copyPlan');
  var downloadLink = el('downloadPlan');

  function composePlan(){
    var focus = el('focus').value;
    var weeks = el('weeks').value;
    var freq = el('freq').value;
    var length = el('length').value;
    var outcome = el('outcome').value || 'Observable change you care about';
    var approaches = Array.from(form.querySelectorAll('input[type=checkbox]:checked')).map(function(i){return i.value});
    var now = new Date().toISOString().slice(0,10);

    var lines = [];
    lines.push('{{BUSINESS_NAME}} — Session Plan');
    lines.push('Generated: ' + now);
    lines.push('Focus: ' + focus);
    lines.push('Outcome to track: ' + outcome);
    lines.push('Commitment: ' + weeks + ' weeks, ' + freq + ' session(s) per week, ' + length);
    lines.push('Approaches: ' + (approaches.length?approaches.join(', '):'custom'));
    lines.push('---');
    lines.push('Week-by-week guide:');

    for(var w=1; w<=Math.min(12,Math.max(1,parseInt(weeks)||1)); w++){
      var note = 'Week ' + w + ': ' + (w===1? 'Start with one micro-habit and one reflection.':'' ) + ' Focus on small wins and tracking.';
      lines.push(note);
    }
    lines.push('Practice prompts:');
    lines.push('- Brief check-in before each session (2 min)');
    lines.push('- One measurable micro-habit tied to the outcome');
    lines.push('\nShare notes with your coach or save in a journal.');

    var full = lines.join('\n');
    output.value = full;

    // prepare download
    var blob = new Blob([full],{type:'text/plain'});
    var url = URL.createObjectURL(blob);
    downloadLink.href = url;
    downloadLink.download = 'session-plan.txt';
  }

  generateBtn.addEventListener('click',function(e){composePlan();});
  clearBtn.addEventListener('click',function(){form.reset();output.value='';downloadLink.href='#';});

  copyBtn.addEventListener('click',function(){
    output.select();
    try{document.execCommand('copy');copyBtn.textContent='Copied';setTimeout(function(){copyBtn.textContent='Copy summary'},1200);}catch(e){alert('Select and copy the text manually.');}
  });

  // Diagnostic quick UI (simple interactions)
  var energyBtns = document.querySelectorAll('#energyScale button');
  energyBtns.forEach(function(b){b.addEventListener('click',function(){energyBtns.forEach(function(x){x.classList.remove('active')});b.classList.add('active');});});
  var sleepBtns = document.querySelectorAll('#sleepScale button');
  sleepBtns.forEach(function(b){b.addEventListener('click',function(){sleepBtns.forEach(function(x){x.classList.remove('active')});b.classList.add('active');});});

  // Habit Builder (7-day checklist)
  var habitForm = el('habitForm');
  var genHabit = el('generateHabit');
  var printHabit = el('printHabit');
  var checklist = el('checklist');

  function weekdayIndex(day){var map={Monday:1,Tuesday:2,Wednesday:3,Thursday:4,Friday:5,Saturday:6,Sunday:0};return map[day]||1}
  function makeChecklist(){
    var name = el('habitName').value.trim() || 'Daily habit';
    var goal = el('habitGoal').value;
    var start = el('startDay').value;
    var startIdx = weekdayIndex(start);
    checklist.innerHTML = '';
    var names = ['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'];
    for(var i=0;i<7;i++){
      var idx = (startIdx + i) % 7;
      var li = document.createElement('li');
      li.innerHTML = '<label><input type="checkbox"> <strong>' + names[idx] + '</strong> — ' + name + ' — ' + goal + '</label>';
      checklist.appendChild(li);
    }
  }

  genHabit.addEventListener('click',function(){makeChecklist();});

  printHabit.addEventListener('click',function(){
    if(!checklist.children.length) makeChecklist();
    var w = window.open('','habit','width=600,height=700');
    var title = (el('habitName').value.trim() || '7-Day Habit');
    var html = '<!doctype html><html><head><meta charset="utf-8"><title>'+title+'</title>'+
      '<style>body{font-family:Arial,Helvetica,sans-serif;padding:20px}h1{color:#234}ol{padding-left:20px}li{margin:10px 0}</style>'+
      '</head><body><h1>'+title+'</h1><ol>';
    Array.from(checklist.children).forEach(function(li){html += '<li>'+li.textContent.trim()+'</li>';});
    html += '</ol><p>Generated from {{BUSINESS_NAME}} — keep a copy with your planner.</p></body></html>';
    w.document.write(html); w.document.close(); w.focus(); setTimeout(function(){w.print();},600);
  });

  // Accessibility: allow Enter on key form buttons
  [generateBtn, genHabit].forEach(function(btn){btn.addEventListener('keypress',function(e){if(e.key==='Enter'){btn.click();}})});
})();"} 
